<template>
  <main class="reconciliation">
    <header class="page-heading">
      <div><p class="eyebrow">ADMIN MASTER / FINANCEIRO</p><h1>Conciliação de assinaturas</h1><p class="muted">Identifique atrasos, confira a recorrência e encontre o que precisa de atenção.</p></div>
      <div class="heading-actions"><button class="button" :disabled="!report || loading || !filtered.length" @click="exportCsv">↓ Exportar CSV</button><button class="button primary" :disabled="loading" @click="load(true)">{{ loading ? 'Consultando Asaas…' : '↻ Atualizar análise' }}</button></div>
    </header>

    <section class="panel filters" aria-label="Filtros da conciliação">
      <div class="period-row">
        <label>Vencimento inicial<input v-model="startDate" type="date" :max="endDate || today" /></label>
        <label>Vencimento final<input v-model="endDate" type="date" :max="today" /></label>
        <button class="button" :disabled="loading" @click="load(false)">Consultar período</button>
        <button class="text-button" :disabled="loading" @click="allHistory">Todo o histórico vencido</button>
        <div class="source-status" v-if="report"><span class="dot" :class="{ warning: !report.complete }"></span>{{ report.environment === 'sandbox' ? 'AMBIENTE DE TESTES' : 'Asaas · produção' }}<small>Consulta: {{ dateTime(report.generated_at) }}{{ report.cached ? ' · cache de até 5 min' : '' }}</small></div>
      </div>
      <div class="filter-grid">
        <label class="search-field">Buscar cliente ou referência<input v-model="search" type="search" placeholder="Nome, e-mail, cobrança ou assinatura…" /></label>
        <label>Gateway<select v-model="gateway"><option value="">Todos</option><option v-for="g in gateways" :key="g" :value="g">{{ gatewayName(g) }}</option></select></label>
        <label>Pagamento<select v-model="method"><option value="">Todos</option><option v-for="m in methods" :key="m" :value="m">{{ methodName(m) }}</option></select></label>
        <label>Autorização Pix<select v-model="authorization"><option value="">Todas</option><option value="ACTIVE">Ativa</option><option value="MISSING">Não localizada</option><option value="CREATED">Aguardando autorização</option><option value="CANCELLED">Cancelada</option><option value="REFUSED">Recusada</option><option value="EXPIRED">Expirada</option><option value="UNKNOWN">Não verificada</option></select></label>
        <label>Plano<select v-model="plan"><option value="">Todos</option><option v-for="p in plans" :key="p" :value="p">{{ p }}</option></select></label>
        <label>Escopo<select v-model="scope"><option value="subscription">Assinaturas e recorrências</option><option value="all">Toda a conta Asaas</option><option value="unmatched">Sem vínculo identificado</option></select></label>
      </div>
      <div class="filter-footer"><span>{{ report ? `${formatDate(report.start_date) || 'Início do histórico'} a ${formatDate(report.end_date)}` : 'Escolha o período ou consulte todo o histórico.' }} · Datas de vencimento · horário de Brasília</span><button class="text-button" @click="clearFilters">Limpar filtros</button></div>
    </section>

    <div v-if="error" class="notice danger" role="alert"><strong>Não foi possível concluir a consulta.</strong> {{ error }}<span v-if="report"> Os dados abaixo são da consulta anterior.</span></div>
    <div v-if="loading" class="notice" role="status"><span class="spinner"></span> Consultando cobranças, assinaturas, autorizações e instruções de débito. Contas maiores podem levar até dois minutos.</div>
    <template v-if="report">
      <div v-if="!report.complete" class="notice amber" role="alert"><strong>Análise parcial.</strong> Os totais representam apenas os registros consultados. Não conclua que uma cobrança ou autorização está ausente enquanto houver fontes incompletas.</div>
      <div v-for="message in sourceErrors" :key="message" class="notice danger" role="alert">{{ message }}</div>
      <div v-if="report.environment === 'sandbox'" class="notice amber">Esta análise usa o sandbox do Asaas. Os valores são de teste.</div>

      <section class="kpi-grid" aria-label="Indicadores financeiros">
        <button class="kpi featured" @click="tab = 'overdue'"><span>Em atraso confirmado</span><strong>{{ currency(totals.overdue) }}</strong><small>{{ overdue.length }} cobranças vencidas no Asaas</small></button>
        <button class="kpi" @click="tab = 'overdue'"><span>Assinaturas com atraso</span><strong>{{ totals.subscriptions }}</strong><small>{{ totals.clients }} clientes identificados</small></button>
        <button class="kpi" @click="tab = 'paid'"><span>Recebido / confirmado</span><strong>{{ currency(totals.paid) }}</strong><small>{{ paid.length }} cobranças com vencimento no período</small></button>
        <div class="kpi"><span>Inadimplência por valor</span><strong>{{ totals.rate.toFixed(1) }}<em>%</em></strong><small>Atrasado ÷ (pago + atrasado)</small></div>
        <button class="kpi" @click="tab = 'review'"><span>Renovações a conferir</span><strong>{{ reviews.length }}</strong><small>Sem valor somado à dívida confirmada</small></button>
        <button class="kpi" @click="method = 'PIX'; tab = 'overdue'"><span>Pix em atraso</span><strong>{{ currency(totals.pix) }}</strong><small>{{ overdue.filter(r => r.method === 'PIX').length }} cobranças precisam de acompanhamento</small></button>
        <div class="kpi"><span>Maior atraso</span><strong>{{ totals.maxDays }} <em>dias</em></strong><small>Média de {{ totals.avgDays }} dias por cobrança vencida</small></div>
        <button class="kpi" @click="onlyFindings = !onlyFindings"><span>Registros com alertas</span><strong>{{ filtered.filter(r => r.findings.length).length }}</strong><small>{{ onlyFindings ? 'Clique para mostrar todos' : 'Clique para filtrar os alertas' }}</small></button>
      </section>

      <section class="chart-grid">
        <article class="panel chart-panel"><div class="section-heading"><div><h2>Tempo em atraso</h2><p>Valor confirmado por faixa</p></div><span class="mini-label">Clique para filtrar</span></div><div class="bars"><button v-for="b in aging" :key="b.label" class="bar-row" @click="age = b.key; tab = 'overdue'"><span>{{ b.label }}<small>{{ b.count }} cobranças</small></span><div class="bar-track"><i :style="{ width: percent(b.amount, agingMax) + '%' }"></i></div><b>{{ currency(b.amount) }}</b></button></div></article>
        <article class="panel chart-panel"><div class="section-heading"><div><h2>Formas de pagamento</h2><p>Composição do valor em atraso</p></div><span class="mini-label">Asaas</span></div><div class="bars"><button v-for="b in paymentGroups" :key="b.key" class="bar-row" @click="method = b.key; tab = 'overdue'"><span>{{ methodName(b.key) }}<small>{{ b.count }} cobranças</small></span><div class="bar-track teal"><i :style="{ width: percent(b.amount, paymentMax) + '%' }"></i></div><b>{{ currency(b.amount) }}</b></button><p v-if="!paymentGroups.length" class="chart-empty">Nenhum atraso confirmado neste recorte.</p></div></article>
        <article class="panel trend-panel"><div class="section-heading"><div><h2>Vencimentos por mês</h2><p>Situação atual das cobranças em cada competência · até 12 meses recentes do recorte</p></div><div class="legend"><span><i class="paid-color"></i>Pago</span><span><i class="due-color"></i>Em atraso</span></div></div><div class="trend" role="img" aria-label="Gráfico de valores pagos e em atraso por mês de vencimento"><div v-for="b in monthly" :key="b.month" class="month-column"><div class="month-values"><span>{{ compactCurrency(b.paid + b.overdue) }}</span></div><div class="month-bars" :title="`${b.month}: pago ${currency(b.paid)}; atrasado ${currency(b.overdue)}`"><div class="month-stack" :style="{ height: percent(b.paid + b.overdue, monthlyMax) + '%' }"><i class="due-color" :style="{ flex: b.overdue || 0 }"></i><i class="paid-color" :style="{ flex: b.paid || 0 }"></i></div></div><span>{{ monthLabel(b.month) }}</span></div><p v-if="!monthly.length" class="chart-empty">Não há cobranças para exibir no gráfico.</p></div></article>
      </section>

      <section class="panel pix-panel"><div class="section-heading"><div><p class="eyebrow">AUDITORIA DA RECORRÊNCIA</p><h2>O Pix está realmente automático?</h2><p>A autorização permite o débito. O modo de geração indica quem cria a cobrança de cada ciclo.</p></div></div><div class="pix-grid"><button @click="method = 'PIX'; authorization = 'ACTIVE'"><span>Autorização ativa</span><strong>{{ pixStats.active }}</strong><small>Cobranças Pix no recorte</small></button><button @click="method = 'PIX'; pixKind = 'automatic'"><span>Vínculo automático confirmado</span><strong>{{ pixStats.linked }}</strong><small>Autorização ou instrução vinculada no Asaas</small></button><button @click="creationMode = 'SUBSCRIPTION'; method = 'PIX'"><span>Asaas gera os ciclos</span><strong>{{ pixStats.subscription }}</strong><small>Modo SUBSCRIPTION</small></button><button @click="creationMode = 'MANUAL'; method = 'PIX'"><span>Aplicação gera os ciclos</span><strong>{{ pixStats.manual }}</strong><small>Modo MANUAL · verificar agendamento</small></button><button @click="method = 'PIX'; pixKind = 'ordinary'"><span>Pix comum</span><strong>{{ pixStats.ordinary }}</strong><small>Sem vínculo automático localizado</small></button><button @click="method = 'PIX'; authorization = 'UNKNOWN'"><span>Autorização não verificada</span><strong>{{ pixStats.unknown }}</strong><small>Consulta indisponível ou vínculo inconclusivo</small></button></div></section>

      <section class="panel table-panel">
        <div class="section-heading"><div><h2>Fila de conciliação</h2><p>{{ visibleRows.length }} registros · filtros e gráficos usam o mesmo recorte</p></div><label class="checkbox"><input v-model="onlyFindings" type="checkbox" /> Somente com alertas</label></div>
        <div class="table-toolbar"><div class="tabs" role="tablist" aria-label="Situação"><button v-for="t in tabs" :key="t.key" role="tab" :aria-selected="tab === t.key" :class="{ active: tab === t.key }" @click="tab = t.key">{{ t.label }} <span>{{ tabCount(t.key) }}</span></button></div><div class="table-controls"><select v-model="age" aria-label="Faixa de atraso"><option value="">Qualquer atraso</option><option v-for="a in aging" :key="a.key" :value="a.key">{{ a.label }}</option></select><select v-model="sort" aria-label="Ordenação"><option value="days">Maior atraso</option><option value="amount">Maior valor</option><option value="name">Cliente A–Z</option></select></div></div>
        <div v-if="pixKind || creationMode" class="active-filters"><span v-if="pixKind">Pix: {{ pixKindName(pixKind) }} <button @click="pixKind = ''" aria-label="Remover filtro de Pix">×</button></span><span v-if="creationMode">Geração: {{ creationMode }} <button @click="creationMode = ''" aria-label="Remover filtro de geração">×</button></span></div>
        <div class="table-scroll"><table><thead><tr><th>Cliente / plano</th><th>Gateway / pagamento</th><th>Vencimento</th><th>Valor</th><th>Autorização Pix</th><th>Conciliação</th><th><span class="sr-only">Detalhes</span></th></tr></thead><tbody><tr v-for="r in pagedRows" :key="r.id"><td><strong>{{ r.name }}</strong><small>{{ r.email || r.customer_id || 'Sem cadastro local' }}</small><span class="plan-badge">{{ r.plan }}</span></td><td><strong>{{ gatewayName(r.gateway) }}</strong><small>{{ methodName(r.method) }}</small><span v-if="r.method === 'PIX'" class="subtle">{{ pixKindName(r.pix_kind) }}</span></td><td><strong>{{ formatDate(r.due_date) }}</strong><small :class="{ 'danger-text': r.classification === 'overdue' }">{{ r.days_overdue ? `${r.days_overdue} dias${r.kind === 'expectation' ? ' desde a previsão' : ' em atraso'}` : statusName(r.payment_status) }}</small></td><td class="amount">{{ r.amount === null ? 'A conferir' : currency(r.amount) }}<small v-if="r.kind === 'expectation'">Sem dívida confirmada</small></td><td><span class="badge" :class="authTone(r.authorization_status)">{{ statusName(r.authorization_status) }}</span><small v-if="r.method === 'PIX'">{{ modeName(r.creation_mode) }}</small></td><td><span class="badge" :class="r.classification === 'overdue' ? 'bad' : r.classification === 'paid' ? 'good' : 'neutral'">{{ classificationName(r.classification) }}</span><small v-if="r.findings.length">{{ r.findings[0] }}<span v-if="r.findings.length > 1"> +{{ r.findings.length - 1 }}</span></small></td><td><button class="text-button" @click="selected = r">Analisar →</button></td></tr><tr v-if="!pagedRows.length"><td colspan="7" class="empty-state"><strong>Nenhum registro neste recorte</strong><p>Altere os filtros ou selecione outra situação para continuar a análise.</p><button class="button" @click="clearFilters">Limpar filtros</button></td></tr></tbody></table></div>
        <footer class="pagination"><span>{{ visibleRows.length ? (page - 1) * pageSize + 1 : 0 }}–{{ Math.min(page * pageSize, visibleRows.length) }} de {{ visibleRows.length }}</span><div><select v-model.number="pageSize" aria-label="Registros por página"><option :value="25">25 por página</option><option :value="50">50 por página</option><option :value="100">100 por página</option></select><button class="button" :disabled="page <= 1" @click="page--">Anterior</button><span>{{ page }} / {{ pageCount }}</span><button class="button" :disabled="page >= pageCount" @click="page++">Próxima</button></div></footer>
      </section>

      <section class="bottom-grid"><article class="panel"><div class="section-heading"><div><h2>Cobertura por gateway</h2><p>Assinaturas locais · inventário completo, independente dos filtros</p></div></div><table class="gateway-table"><thead><tr><th>Gateway</th><th>Assinaturas</th><th>Fonte financeira</th></tr></thead><tbody><tr v-for="g in gatewayInventory" :key="g.key"><td>{{ gatewayName(g.key) }}</td><td>{{ g.count }}</td><td><span class="badge" :class="g.key === 'asaas' ? 'good' : 'neutral'">{{ g.key === 'asaas' ? 'API Asaas' : 'Cadastro local · conferir no gateway' }}</span></td></tr></tbody></table></article><article class="panel"><div class="section-heading"><div><h2>Qualidade da consulta</h2><p>Todos os resultados paginados · consulta somente de leitura</p></div></div><div class="coverage-list"><div v-for="(source, key) in report.coverage" :key="key"><span>{{ sourceName(String(key)) }}<small v-if="source.error">{{ source.error }}</small></span><strong>{{ source.count }}</strong><span class="badge" :class="source.complete ? 'good' : 'bad'">{{ source.complete ? 'Completa' : 'Parcial' }}</span></div></div></article></section>
      <details class="panel methodology"><summary>Como interpretar esta conciliação</summary><p>O atraso confirmado considera cobranças não excluídas com vencimento anterior a hoje e status PENDING, OVERDUE ou CREDIT_CARD_CAPTURE_REFUSED. Pagamentos RECEIVED, CONFIRMED e RECEIVED_IN_CASH compõem o recebido/confirmado. Outros status ficam na aba “Outros”, sem entrar no cálculo de inadimplência.</p><p>Uma renovação esperada usa a próxima data de cobrança registrada ou, na ausência dela, o dia seguinte ao fim da vigência local. É um indício para investigação: não prova dívida e não usa MRR como valor da cobrança. Cancelamentos identificados não geram expectativa de renovação.</p><p>O relatório mostra a situação atual das cobranças cujo vencimento está no período. Não reconstrói o saldo histórico de uma data passada. Uma instrução Pix DONE não substitui a confirmação financeira da cobrança. Nos outros gateways, a análise depende dos dados locais.</p><p>Escopo “Toda a conta Asaas” também inclui cobranças sem assinatura identificada. A data da consulta e a cobertura devem acompanhar qualquer exportação. Nenhuma cobrança é criada, cancelada ou reprocessada por esta tela.</p><a href="https://docs.asaas.com/docs/pix-automatico" target="_blank" rel="noopener noreferrer">Consultar documentação do Pix Automático ↗</a></details>
    </template>
    <section v-else-if="!loading && !error" class="panel empty-state"><h2>Prepare sua conciliação</h2><p>Consulte o Asaas para comparar cobranças e recorrências com as assinaturas cadastradas.</p><button class="button primary" @click="load(false)">Consultar Asaas</button></section>

    <dialog ref="detailDialog" class="detail-dialog" @close="selected = null" @click="closeBackdrop">
      <template v-if="selected"><header><div><p class="eyebrow">ANÁLISE DA PENDÊNCIA</p><h2>{{ selected.name }}</h2><p class="muted">{{ selected.email }}</p></div><button class="button" @click="selected = null" aria-label="Fechar análise">✕</button></header><div class="detail-body"><div class="detail-summary"><span class="badge" :class="selected.classification === 'overdue' ? 'bad' : 'neutral'">{{ classificationName(selected.classification) }}</span><strong>{{ selected.amount === null ? 'Valor não confirmado' : currency(selected.amount) }}</strong><p>Vencimento {{ formatDate(selected.due_date) }} · {{ gatewayName(selected.gateway) }} · {{ methodName(selected.method) }}</p></div><section><h3>Pontos de atenção</h3><ul v-if="selected.findings.length"><li v-for="f in selected.findings" :key="f">{{ f }}</li></ul><p v-else>Sem divergências identificadas neste registro.</p><p class="notice">{{ recommendation(selected) }}</p></section><section><h3>Pagamento e assinatura</h3><dl><dt>Status da cobrança</dt><dd>{{ statusName(selected.payment_status) }}</dd><dt>Status local</dt><dd>{{ selected.local_status || 'Sem vínculo' }}</dd><dt>Status no Asaas</dt><dd>{{ selected.remote_status || 'Não informado' }}</dd><dt>Forma local / Asaas</dt><dd>{{ selected.local_method || '—' }} / {{ selected.method }}</dd><dt>Valor líquido informado</dt><dd>{{ selected.net_amount === null ? '—' : currency(selected.net_amount) }}</dd><dt>Pagamento registrado</dt><dd>{{ formatDate(selected.paid_date) || '—' }}</dd><dt>ID da cobrança</dt><dd>{{ selected.payment_id || 'Não localizada' }}</dd><dt>ID da assinatura Asaas</dt><dd>{{ selected.remote_subscription_id || 'Não identificado' }}</dd><dt>ID do cliente Asaas</dt><dd>{{ selected.customer_id || '—' }}</dd><dt>Referência externa</dt><dd>{{ selected.external_reference || '—' }}</dd></dl><a v-if="safeInvoice(selected.invoice_url)" :href="safeInvoice(selected.invoice_url)" target="_blank" rel="noopener noreferrer" class="button">Abrir cobrança no Asaas ↗</a></section><section v-if="selected.method === 'PIX'"><h3>Diagnóstico do Pix Automático</h3><dl><dt>Vínculo na cobrança</dt><dd>{{ pixKindName(selected.pix_kind) }}</dd><dt>Autorização no Asaas</dt><dd>{{ statusName(selected.authorization_status) }}</dd><dt>Autorização no cadastro local</dt><dd>{{ selected.local_authorization_status || 'Não registrada' }}</dd><dt>ID da autorização</dt><dd>{{ selected.authorization_id || 'Não localizado' }}</dd><dt>Criação dos próximos ciclos</dt><dd>{{ modeName(selected.creation_mode) }}</dd><dt>Política de retentativa</dt><dd>{{ selected.retry_policy || 'Não informada' }}</dd></dl><div v-if="selected.customer_authorizations?.length" class="instruction"><strong>Autorizações do cliente sem vínculo comprovado</strong><p v-for="a in selected.customer_authorizations" :key="a.id">{{ a.id }} · {{ statusName(a.status) }} · {{ modeName(a.creation_mode) }}</p></div><div v-for="i in selected.instructions" :key="i.id" class="instruction"><strong>{{ statusName(i.status) }}</strong><small>{{ i.id }} · {{ formatDate(i.due_date) }}</small><p v-if="i.refusal_reason">Motivo retornado: {{ i.refusal_reason }}</p></div><p v-if="!selected.instructions.length" class="muted">Nenhuma instrução vinculada localizada nesta consulta. Confira a cobertura antes de concluir ausência.</p></section><section><h3>Histórico da assinatura no período</h3><div v-for="r in history" :key="r.id" class="history-row"><span>{{ formatDate(r.due_date) }}<small>{{ r.payment_id || 'Previsão local' }}</small></span><span>{{ r.amount === null ? 'A conferir' : currency(r.amount) }}</span><span>{{ classificationName(r.classification) }}</span></div></section></div><footer><button class="button" @click="selected = null">Fechar análise</button></footer></template>
    </dialog>
  </main>
</template>

<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import api from '../../services/api';

type Row = { id: string; kind: string; scope: string; subscription_key: string; local_subscription_id: number | null; user_id: number | null; name: string; email: string; plan: string; gateway: string; method: string; local_method: string | null; local_status: string | null; remote_status: string | null; payment_id: string | null; remote_subscription_id: string | null; customer_id: string | null; external_reference: string | null; due_date: string; days_overdue: number; amount: number | null; net_amount: number | null; payment_status: string; paid_date: string | null; classification: string; evidence: string; invoice_url: string | null; findings: string[]; pix_kind: string; authorization_id: string | null; authorization_status: string; local_authorization_status: string | null; creation_mode: string; retry_policy: string | null; customer_authorizations?: { id: string; status: string; creation_mode: string }[]; instructions: { id: string; status: string; due_date: string; refusal_reason: unknown }[] };
type Report = { rows: Row[]; subscriptions: { id: number; gateway: string }[]; coverage: Record<string, { complete: boolean; count: number; error: string | null }>; complete: boolean; environment: string; generated_at: string; start_date: string | null; end_date: string; as_of: string; cached: boolean };
const report = ref<Report | null>(null), loading = ref(false), error = ref('');
const today = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Sao_Paulo', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const startDate = ref(''), endDate = ref(''), search = ref(''), gateway = ref(''), method = ref(''), authorization = ref(''), plan = ref(''), scope = ref('subscription');
const tab = ref('overdue'), age = ref(''), sort = ref('days'), onlyFindings = ref(false), pixKind = ref(''), creationMode = ref(''), page = ref(1), pageSize = ref(25);
const selected = ref<Row | null>(null), detailDialog = ref<HTMLDialogElement | null>(null);
let controller: AbortController | undefined;
const sourceErrors = computed(() => [...new Set(Object.values(report.value?.coverage || {}).map(s => s.error).filter((s): s is string => Boolean(s)))]);
const allRows = computed(() => report.value?.rows || []);
const gateways = computed(() => [...new Set([...allRows.value.map(r => r.gateway), ...(report.value?.subscriptions || []).map(s => s.gateway)])].sort());
const methods = computed(() => [...new Set(allRows.value.map(r => r.method))].sort());
const plans = computed(() => [...new Set(allRows.value.map(r => r.plan))].sort());
const normalize = (s: string) => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const filtered = computed(() => allRows.value.filter(r => (!gateway.value || r.gateway === gateway.value) && (!method.value || r.method === method.value) && (!authorization.value || r.authorization_status === authorization.value) && (!plan.value || r.plan === plan.value) && (scope.value === 'all' || r.scope === scope.value) && (!pixKind.value || r.pix_kind === pixKind.value) && (!creationMode.value || r.creation_mode === creationMode.value) && (!search.value || normalize([r.name, r.email, r.payment_id, r.remote_subscription_id, r.customer_id, r.external_reference].join(' ')).includes(normalize(search.value)))));
const overdue = computed(() => filtered.value.filter(r => r.classification === 'overdue'));
const paid = computed(() => filtered.value.filter(r => r.classification === 'paid'));
const reviews = computed(() => filtered.value.filter(r => r.classification === 'review'));
const sum = (rows: Row[]) => rows.reduce((n, r) => n + Math.round((r.amount || 0) * 100), 0) / 100;
const totals = computed(() => { const debt = sum(overdue.value), received = sum(paid.value); return { overdue: debt, paid: received, subscriptions: new Set(overdue.value.filter(r => r.scope === 'subscription').map(r => r.subscription_key)).size, clients: new Set(overdue.value.map(r => r.user_id || r.customer_id).filter(Boolean)).size, rate: debt + received ? debt / (debt + received) * 100 : 0, pix: sum(overdue.value.filter(r => r.method === 'PIX')), maxDays: Math.max(0, ...overdue.value.map(r => r.days_overdue)), avgDays: overdue.value.length ? Math.round(overdue.value.reduce((n, r) => n + r.days_overdue, 0) / overdue.value.length) : 0 }; });
const ageRanges = [{ key: '1-7', label: '1–7 dias', min: 1, max: 7 }, { key: '8-15', label: '8–15 dias', min: 8, max: 15 }, { key: '16-30', label: '16–30 dias', min: 16, max: 30 }, { key: '31-60', label: '31–60 dias', min: 31, max: 60 }, { key: '61+', label: 'Mais de 60 dias', min: 61, max: Infinity }];
const aging = computed(() => ageRanges.map(b => { const rows = overdue.value.filter(r => r.days_overdue >= b.min && r.days_overdue <= b.max); return { ...b, amount: sum(rows), count: rows.length }; }));
const agingMax = computed(() => Math.max(1, ...aging.value.map(b => b.amount)));
const paymentGroups = computed(() => [...new Set(overdue.value.map(r => r.method))].map(key => { const rows = overdue.value.filter(r => r.method === key); return { key, amount: sum(rows), count: rows.length }; }).sort((a, b) => b.amount - a.amount));
const paymentMax = computed(() => Math.max(1, ...paymentGroups.value.map(b => b.amount)));
const monthly = computed(() => { const groups = new Map<string, { month: string; paid: number; overdue: number }>(); for (const r of filtered.value) { if (!['overdue', 'paid'].includes(r.classification)) continue; const key = r.due_date.slice(0, 7); const b = groups.get(key) || { month: key, paid: 0, overdue: 0 }; if (r.classification === 'paid') b.paid += r.amount || 0; else b.overdue += r.amount || 0; groups.set(key, b); } return [...groups.values()].sort((a, b) => a.month.localeCompare(b.month)).slice(-12); });
const monthlyMax = computed(() => Math.max(1, ...monthly.value.map(b => b.paid + b.overdue)));
const pixStats = computed(() => { const rows = filtered.value.filter(r => r.method === 'PIX' && r.kind === 'payment'); return { active: rows.filter(r => r.authorization_status === 'ACTIVE').length, linked: rows.filter(r => r.pix_kind === 'automatic').length, subscription: rows.filter(r => r.creation_mode === 'SUBSCRIPTION').length, manual: rows.filter(r => r.creation_mode === 'MANUAL').length, ordinary: rows.filter(r => r.pix_kind === 'ordinary').length, unknown: rows.filter(r => r.authorization_status === 'UNKNOWN').length }; });
const gatewayInventory = computed(() => gateways.value.map(key => ({ key, count: (report.value?.subscriptions || []).filter(s => s.gateway === key).length })));
const tabs = [{ key: 'overdue', label: 'Em atraso' }, { key: 'review', label: 'A conferir' }, { key: 'paid', label: 'Pagas' }, { key: 'other', label: 'Outros' }, { key: 'all', label: 'Todos' }];
const tabCount = (key: string) => filtered.value.filter(r => key === 'all' || r.classification === key).length;
const visibleRows = computed(() => { const range = ageRanges.find(a => a.key === age.value); return filtered.value.filter(r => (tab.value === 'all' || r.classification === tab.value) && (!onlyFindings.value || r.findings.length) && (!range || (r.days_overdue >= range.min && r.days_overdue <= range.max))).sort((a, b) => sort.value === 'name' ? a.name.localeCompare(b.name, 'pt-BR') : sort.value === 'amount' ? (b.amount || 0) - (a.amount || 0) : b.days_overdue - a.days_overdue); });
const pageCount = computed(() => Math.max(1, Math.ceil(visibleRows.value.length / pageSize.value)));
const pagedRows = computed(() => visibleRows.value.slice((page.value - 1) * pageSize.value, page.value * pageSize.value));
watch([visibleRows, pageSize], () => { page.value = 1; });
const history = computed(() => selected.value ? allRows.value.filter(r => (r.subscription_key === selected.value?.subscription_key || (selected.value?.local_subscription_id && r.local_subscription_id === selected.value.local_subscription_id))).sort((a, b) => b.due_date.localeCompare(a.due_date)) : []);
watch(selected, async value => { await nextTick(); if (value && !detailDialog.value?.open) detailDialog.value?.showModal(); else if (!value) detailDialog.value?.close(); });
function closeBackdrop(event: MouseEvent) { if (event.target === detailDialog.value) { const rect = detailDialog.value!.getBoundingClientRect(); if (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) selected.value = null; } }
function clearFilters() { search.value = gateway.value = method.value = authorization.value = plan.value = age.value = pixKind.value = creationMode.value = ''; scope.value = 'subscription'; onlyFindings.value = false; }
function allHistory() { startDate.value = endDate.value = ''; load(false); }
async function load(refresh: boolean) { if (loading.value) return; if (startDate.value && endDate.value && startDate.value > endDate.value) { error.value = 'A data inicial deve ser anterior à data final.'; return; } loading.value = true; error.value = ''; controller = new AbortController(); try { const { data } = await api.get<Report>('/admin/billing-reconciliation', { params: { start_date: startDate.value || undefined, end_date: endDate.value || undefined, refresh }, signal: controller.signal, timeout: 150000 }); report.value = data; selected.value = null; } catch (e: any) { if (e?.code !== 'ERR_CANCELED') error.value = typeof e?.response?.data?.detail === 'string' ? e.response.data.detail : 'Falha de conexão ou tempo excedido. Tente um período menor.'; } finally { loading.value = false; } }
