const methodName = (v: string) => (({ PIX: 'Pix', CREDIT_CARD: 'Cartão de crédito', BOLETO: 'Boleto', UNDEFINED: 'Não informado', credit_card: 'Cartão de crédito', pix: 'Pix' } as Record<string, string>)[v] || v);
