const pixKindName = (v: string) => (({ automatic: 'Pix Automático confirmado', ordinary: 'Pix comum', unverified: 'Vínculo não confirmado', unknown: 'Não verificado', not_pix: 'Não se aplica' } as Record<string, string>)[v] || v);
const statusName = (v: string) => (({ ACTIVE: 'Ativa', CREATED: 'Aguardando autorização', CANCELLED: 'Cancelada', REFUSED: 'Recusada', EXPIRED: 'Expirada', MISSING: 'Não localizada', UNKNOWN: 'Não verificada', NOT_APPLICABLE: 'Não se aplica', PENDING: 'Pendente', OVERDUE: 'Vencida', RECEIVED: 'Recebida', CONFIRMED: 'Confirmada', RECEIVED_IN_CASH: 'Recebida em dinheiro', UNVERIFIED: 'A conferir', DONE: 'Instrução concluída', SCHEDULED: 'Agendada', AWAITING_REQUEST: 'Aguardando processamento' } as Record<string, string>)[v] || v);
const modeName = (v: string) => (({ SUBSCRIPTION: 'Asaas gera as cobranças', MANUAL: 'Aplicação gera as cobranças', UNKNOWN: 'Modo não informado', NOT_APPLICABLE: 'Não se aplica' } as Record<string, string>)[v] || v);
const sourceName = (v: string) => (({ payments: 'Cobranças', subscriptions: 'Assinaturas', authorizations: 'Autorizações Pix', instructions: 'Instruções de débito' } as Record<string, string>)[v] || v);
const authTone = (v: string) => v === 'ACTIVE' ? 'good' : ['CANCELLED', 'REFUSED', 'EXPIRED', 'MISSING'].includes(v) ? 'bad' : 'neutral';
function recommendation(r: Row) { if (r.kind === 'expectation') return 'Confira o contrato, a vigência e a cobrança no gateway antes de registrar inadimplência ou emitir uma nova cobrança.'; if (r.classification === 'paid') return 'Pagamento confirmado pelo Asaas. Confira a vigência local e os eventos de integração se o acesso do cliente estiver bloqueado.'; if (r.method === 'PIX' && r.authorization_status !== 'ACTIVE') return 'Confira o estado da autorização no Asaas e a instrução do ciclo. Pix recorrente depende de autorização ativa do pagador.'; if (r.creation_mode === 'MANUAL') return 'Confira se a aplicação gerou a cobrança deste ciclo e examine as instruções de débito e eventuais recusas.'; return 'Confira o status da cobrança e o histórico da assinatura antes de tomar uma ação de cobrança.'; }
